insert into public.services (id, title, division, icon, description, image, anchor, active, featured, sort_order, created_at, updated_at) values
  ('s_ecu-calibration-remapping', 'ECU Calibration & Remapping', 'Performance', 'ecu', 'Specialising in ECU calibration across a wide range of manufacturers. Every map is optimised for boost, air/fuel ratio, ignition timing and torque management etc. - balancing real performance gains with long-term reliability.', '', 'ecu-remapping', true, true, 0, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_dastek-unichip-installation', 'Dastek Unichip Installation', 'Performance', 'ecu', 'Advanced accredited dealer with 20+ years'' experience in installation and tuning across various manufacturer platforms - covering plug-and-play, warranty-conscious ECU control and options such as derating, road-speed regulation or removal, immobiliser functions and 5-map switching solutions.', '', 'unichip', true, true, 1, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_dyno-validation', 'Dyno Validation', 'Performance', 'dyno', 'In-house loading and inertia runs with calibrated power readings. Real-time EGT, AFR, wheel Nm, speed, kW, boost and many more monitoring readings available.', '', 'dyno', true, true, 2, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_performance-exhaust-systems', 'Performance Exhaust Systems', 'Performance', 'exhaust', 'High-quality, custom-manufactured performance exhausts - from bolt-on systems to bespoke downpipes. Precision-welded to an exacting standard for a premium finish, cleaner flow and an unmistakable tone.', '', 'exhaust', true, true, 3, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_turbo-upgrades', 'Turbo Upgrades', 'Performance', 'turbo', 'Upgraded turbochargers and supporting hardware for more boost and stronger response.', '', 'conversions', true, false, 4, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_hybrid-turbo-conversions', 'Hybrid Turbo Conversions', 'Performance', 'turbo', 'Hybrid and big-turbo conversions for a serious step up in performance.', '', 'conversions', true, false, 5, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_intercooler-upgrades', 'Intercooler Upgrades', 'Performance', 'intercooler', 'Bolt-on, larger and more efficient intercoolers - up to 200% capacity increase - for cooler charge air, delivering safer, more consistent power. Custom-built intercoolers to suit performance-specific applications.', '', '', true, false, 6, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_fuel-system-upgrades', 'Fuel System Upgrades', 'Performance', 'additive', 'Fuel lines, pumps and injectors to safely support higher fuelling demands. Catering for various fuels such as ethanol, methanol and race fuels.', '', '', true, false, 7, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_economy-tuning', 'Economy Tuning', 'Performance', 'gauge', 'We provide economy tunes that save fuel while still adding power to your vehicle.', '', '', true, false, 8, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_intake-systems', 'Intake Systems', 'Performance', 'intake', 'Performance cold-air induction and intake manifold upgrades for improved airflow.', '', '', true, false, 9, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_performance-diagnostics', 'Performance Diagnostics', 'Performance', 'diagnostics', 'Data logging and analysis to verify tuned setups, ensuring safety and reliability. Fault finding to keep tuned setups running safely and reliably.', '', '', true, false, 10, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_custom-performance-packages', 'Custom Performance Packages', 'Performance', 'star', 'Tailored builds from mild street setups to maximum-power projects.', '', '', true, false, 11, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_minor-services', 'Minor Services', 'Services & Repairs', 'wrench', 'Regular servicing using quality oils, filters and manufacturer recommendations.', '', '', true, true, 12, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_major-services', 'Major Services', 'Services & Repairs', 'wrench', 'Comprehensive scheduled maintenance including all required inspections and replacements.', '', '', true, true, 13, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_mechanical-repairs', 'Mechanical Repairs', 'Services & Repairs', 'cog', 'Professional repairs for engine, suspension, braking and drivetrain components.', '', '', true, false, 14, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_diagnostics', 'Diagnostics', 'Services & Repairs', 'diagnostics', 'Advanced fault finding using professional diagnostic equipment and dyno diagnostics.', '', '', true, false, 15, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_brake-services', 'Brake Services', 'Services & Repairs', 'gauge', 'Inspection, replacement and maintenance of braking systems.', '', '', true, false, 16, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_cooling-systems', 'Cooling Systems', 'Services & Repairs', 'bolt', 'Radiators, auxiliary coolant systems, thermo-regulating systems and overheating diagnosis.', '', '', true, false, 17, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_detailing-services', 'Detailing Services', 'Services & Repairs', 'sparkles', 'All vehicles are washed after a service before leaving the workshop - tyre shine and window washer fluid included. Optional extras: polishing, glazing, ceramic coating, nano coating, engine bay and undercarriage wash.', '', '', true, false, 18, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z'),
  ('s_vehicle-inspections', 'Vehicle Inspections', 'Services & Repairs', 'shield', 'Pre-purchase inspections, safety inspections and general vehicle health checks.', '', '', true, false, 19, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.327Z')
insert into public.stages (id, label, name, tagline, description, requirements, benefits, note, icon, active, sort_order, created_at, updated_at) values
  ('st_stage-1', '1', 'Stage 1', 'Software Only', 'A pure ECU or TCU software remap - safe, reliable gains with no hardware changes required.', '["Basic ECU software / remap","No hardware upgrades required"]'::jsonb, '["More Power","Better Response","Improved Driveability","Reliable Performance","Improved Fuel Consumption"]'::jsonb, '', 'ecu', true, 0, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.328Z'),
  ('st_stage-1-plus', '1+', 'Stage 1+', 'Light Performance Upgrades', 'Light bolt-on hardware paired with customised tune adjustments, creating a Stage 1+ tune for a noticeable step up.', '["Decat or downpipe","Optional upgraded exhaust system","Optional intake / induction","Optional Stage 1 TCU (gearbox) tune"]'::jsonb, '["More Power","Better Response","Improved Driveability","Reliable Performance","Improved Fuel Consumption"]'::jsonb, '', 'exhaust', true, 1, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.328Z'),
  ('st_stage-2', '2', 'Stage 2', 'Intermediate Performance Build', 'A balanced intermediate build - supporting hardware plus a Stage 2 software tune.', '["Downpipe","Intake / induction upgrade","Exhaust mid-box delete or full upgraded exhaust","Intercooler upgrade or Water-Methanol Injection (WMI)","Stage 2 ECU software tune","Optional Stage 1 or 2 TCU tune"]'::jsonb, '["More Power","Better Response","Improved Driveability","Reliable Performance"]'::jsonb, '', 'dyno', true, 2, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.328Z'),
  ('st_stage-2-plus', '2+', 'Stage 2+', 'Advanced Performance Setup', 'Advanced setup consisting of Stage 2 hardware but introducing a hybrid turbo with matched Stage 2+ software.', '["Downpipe","Intake / induction upgrade","Full upgraded exhaust","Boost Pipes","Intercooler upgrade","Water-Methanol Injection (WMI)","Hybrid turbos","Stage 2+ ECU software tune","Supportive ECU tune"]'::jsonb, '["More Power","Better Response","Improved Driveability","Reliable Performance"]'::jsonb, '', 'turbo', true, 3, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.328Z'),
  ('st_stage-3', '3', 'Stage 3', 'High Performance / Maximum Power Build', 'Our maximum-power build - full supporting hardware, a bigger turbo and optional forged internals.', '["Downpipe and full exhaust system","Intercooler upgrade","Water-Methanol Injection (WMI)","Upgraded larger / bigger turbo","Optional forged engine internals","Stage 3 ECU software tune","Stage 2+ / 3 TCU software","Optional performance modifications"]'::jsonb, '["Maximum Power","Track-Like Response","Maintaining Driveability","High RPM Power Band","Race Car Feel"]'::jsonb, 'The above are the basic requirements for a Stage 3 package - additional upgrades and modifications can be added.', 'stage', true, 4, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.328Z')
