insert into public.faqs (id, question, answer, category, featured, active, sort_order, created_at, updated_at) values
  ('f_what-makes-venom-racing-different-from-a-g', 'What makes Venom Racing different from a general workshop?', 'Venom Racing stands apart through custom dyno tuning, advanced diagnostics, complete performance builds and personal customer service, all led by an experienced master tuner. Unlike conventional workshops that rely on generic solutions, every vehicle is assessed, tested and calibrated according to its specific hardware, fuel, condition and performance goals to deliver safe, reliable and measurable results.', 'General', false, true, 0, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_what-are-your-operating-hours', 'What are your operating hours?', 'We''re open Monday to Friday, 08:00 to 17:00. Get in touch via phone or WhatsApp to book a consultation.', 'General', false, true, 1, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_will-tuning-void-my-vehicle', 'Will tuning void my vehicle''s warranty?', 'A Dastek Unichip is a piggyback system that doesn''t alter the factory ECU file, which is why it''s a common choice for warranty-sensitive vehicles. Direct ECU remaps are a separate discussion - we''ll talk you through the trade-offs for your specific vehicle at consultation.', 'ECU Tuning & Unichip', true, true, 2, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_what-is-the-5-map-switch-system', 'What is the 5-map switch system?', 'Our Unichip installs include an in-cab switch giving you up to 5 tuned profiles: Immobiliser, Stock, Towing, Consumption, and Performance - letting you match engine behaviour to what you’re doing that day.', 'ECU Tuning & Unichip', true, true, 3, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_which-vehicle-types-does-dastek-unichip-tu', 'Which vehicle types does Dastek Unichip tuning suit?', 'We cover most manufacturers from classic to modern vehicle platforms, from utility vehicles to supercars. Get in touch to confirm compatibility for your vehicle.', 'ECU Tuning & Unichip', true, true, 4, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_do-you-build-custom-performance-exhaust-sy', 'Do you build custom performance exhaust systems?', 'Yes - we manufacture high-quality performance exhaust systems in-house, from bolt-on systems to bespoke downpipes and headers, precision-welded to an exacting standard for a premium finish and cleaner flow.', 'Fabrication & Conversions', false, true, 5, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_do-you-do-full-engine-conversions', 'Do you do full engine conversions?', 'Yes - including fully forged engine conversions, custom turbocharger installations, and structural welding for non-standard engine builds.', 'Fabrication & Conversions', false, true, 6, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_how-long-does-a-typical-installation-take', 'How long does a typical installation take?', 'Turnaround depends on the service - hardware installs and dyno tuning are usually same-day, while fabrication work varies with complexity. We''ll confirm a timeline at your consultation.', 'Booking & Process', true, true, 7, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z'),
  ('f_how-do-i-get-a-quote', 'How do I get a quote?', 'Use the quote request form on our Contact page, or reach us directly by phone or WhatsApp - we''ll ask a few questions about your vehicle and goals before booking an inspection.', 'Booking & Process', false, true, 8, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.329Z')
insert into public.page_sections (id, page, section, title, body, icon, image, active, sort_order, created_at, updated_at) values
  ('ps_about_feature_our-mission', 'about', 'feature', 'Our Mission', 'To deliver validated performance work that owners can trust — measured results, not marketing promises.', '', '', true, 0, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_about_feature_accreditation', 'about', 'feature', 'Accreditation', 'RMI Accredited, meeting manufacturer-level standards on tooling, safety and technician qualification.', '', '', true, 1, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_about_feature_master-tuner', 'about', 'feature', 'Master Tuner', 'In-house professional development and calibration of our own custom ECU and TCU staged software files.', '', '', true, 2, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_about_feature_in-house-craft', 'about', 'feature', 'In-House Craft', 'Fabrication of intercoolers, boost pipes, exhausts, manifolds and long-range tanks — TIG-welded aluminium and stainless steel — plus engine builds and other performance modifications, carried out on-site by our own skilled technicians.', '', '', true, 3, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_feature_rmi-accredited', 'index', 'feature', 'RMI Accredited', 'Manufacturer-level standards on tooling, safety and technician qualification.', '', '', true, 4, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_feature_remote-tuning-solutions', 'index', 'feature', 'Remote Tuning Solutions', 'We provide professional remote tuning solutions for workshops and performance specialists worldwide, delivering reliable calibrations backed by years of experience.', '', '', true, 5, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_feature_in-house-fabrication', 'index', 'feature', 'In-House Fabrication', 'Precision fabrication and performance work carried out on-site by our own skilled technicians — top-quality, guaranteed.', '', '', true, 6, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_feature_validated-results', 'index', 'feature', 'Validated Results', 'Every calibration is professionally validated on the dyno or V-Box, proven to ensure maximum performance, safety and long-term reliability. No ''load and go'' tuning — every vehicle gets data logged, tested and verified.', '', '', true, 7, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_experienced-technicians', 'services', 'feature', 'Experienced Technicians', 'Skilled, experienced hands you can trust with any vehicle.', '', '', true, 8, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_state-of-the-art-diagnostics', 'services', 'feature', 'State-of-the-Art Diagnostics', 'Modern computerised diagnostic equipment for accurate fault finding.', '', '', true, 9, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_genuine-quality-parts', 'services', 'feature', 'Genuine & Quality Parts', 'Quality, fit-for-purpose replacement parts — no shortcuts.', '', '', true, 10, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_honest-workmanship', 'services', 'feature', 'Honest Workmanship', 'Work done properly the first time, with integrity.', '', '', true, 11, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_transparent-communication', 'services', 'feature', 'Transparent Communication', 'Clear updates and no surprises on your bill.', '', '', true, 12, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_services_feature_reliable-turnaround', 'services', 'feature', 'Reliable Turnaround', 'Your vehicle back to you when we promise.', '', '', true, 13, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_process_book-consultation', 'index', 'process', 'Book Consultation', 'Tell us about your vehicle and goals.', '', '', true, 14, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_process_vehicle-inspection', 'index', 'process', 'Vehicle Inspection', 'We assess the platform and current setup.', '', '', true, 15, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_process_custom-recommendation', 'index', 'process', 'Custom Recommendation', 'A tailored plan — software, hardware or fabrication to suit your needs.', '', '', true, 16, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_process_installation-tuning', 'index', 'process', 'Installation / Tuning', 'Work carried out in-house by our skilled technicians.', '', '', true, 17, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_index_process_testing-delivery', 'index', 'process', 'Testing & Delivery', 'Dyno-validated and/or V-Box results with data logging before handover.', '', '', true, 18, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
  ('ps_performance_process_book-consultation', 'performance', 'process', 'Book Consultation', 'Tell us about your vehicle and goals.', '', '', true, 19, '2026-08-20T10:08:16.822Z', '2026-08-20T10:08:19.329Z'),
