insert into public.seo (id, page, title, description, og_title, og_description, og_image, active, sort_order, created_at, updated_at) values
  ('seo_about', 'about', 'About Us | Venom Racing eMalahleni', 'Venom Racing is an RMI Accredited performance workshop in eMalahleni, Mpumalanga — official Dastek Unichip dealer specialising in ECU remapping, dyno testing and exhaust fabrication.', 'About Venom Racing', 'RMI Accredited performance workshop in eMalahleni, Mpumalanga.', 'assets/images/social/og-image.jpg', true, 0, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_contact', 'contact', 'Contact Us | Venom Racing eMalahleni', 'Contact Venom Racing for ECU tuning, Dastek Unichip installs, exhaust fabrication and engine conversions. Call 082 852 0680 or request a quote online.', 'Contact Venom Racing', 'Get in touch with Venom Racing — phone, WhatsApp, email and workshop address.', 'assets/images/social/og-image.jpg', true, 1, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_faqs', 'faqs', 'FAQs | Venom Racing eMalahleni', 'Frequently asked questions about ECU tuning, Dastek Unichip installs, exhaust fabrication, engine conversions, warranty impact, and booking with Venom Racing.', 'FAQs | Venom Racing', 'Frequently asked questions about tuning, fabrication and booking.', 'assets/images/social/og-image.jpg', true, 2, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_gallery', 'gallery', 'Gallery | Venom Racing eMalahleni', 'Photos from inside the Venom Racing workshop — dyno testing, exhaust fabrication, ECU tuning and completed performance builds.', 'Gallery | Venom Racing', 'Photos from inside the Venom Racing performance workshop.', 'assets/images/social/og-image.jpg', true, 3, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_index', 'index', 'Venom Racing | Performance ECU Tuning, Dyno &amp; Fabrication in eMalahleni', 'Venom Racing is an RMI Accredited performance workshop in eMalahleni, Mpumalanga — official Dastek Unichip dealer specialising in ECU remapping, dyno testing, custom exhaust fabrication and turbo conversions.', 'Venom Racing | Performance ECU Tuning, Dyno &amp; Fabrication', 'RMI Accredited performance workshop in eMalahleni. Official Dastek Unichip dealer.', 'assets/images/social/og-image.jpg', true, 4, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_performance', 'performance', 'Performance | Venom Racing eMalahleni', 'Venom Racing''s performance division — ECU calibration &amp; remapping, Dastek Unichip, dyno validation, performance exhausts, turbo upgrades, hybrid conversions, intercooler, fuel &amp; intake upgrades and custom performance packages.', 'Performance | Venom Racing', 'ECU calibration, dyno validation, performance exhausts, turbo upgrades, hybrid conversions and custom performance packages.', 'assets/images/social/og-image.jpg', true, 5, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_privacy', 'privacy', 'Privacy Policy | Venom Racing', 'Venom Racing''s privacy policy — how we collect, use, and protect your personal information.', 'Privacy Policy | Venom Racing', 'Venom Racing''s privacy policy.', 'assets/images/social/og-image.jpg', true, 6, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_reviews', 'reviews', 'Customer Reviews | Venom Racing eMalahleni', 'Read customer reviews for Venom Racing — RMI Accredited performance workshop and official Dastek Unichip dealer in eMalahleni.', 'Customer Reviews | Venom Racing', 'Read reviews from Venom Racing customers.', 'assets/images/social/og-image.jpg', true, 7, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_services', 'services', 'Services &amp; Repairs | Venom Racing eMalahleni', 'Professional vehicle servicing, maintenance and repairs at Venom Racing eMalahleni — minor &amp; major services, mechanical repairs, diagnostics, brakes, cooling, air conditioning and vehicle inspections.', 'Services &amp; Repairs | Venom Racing', 'Professional servicing, maintenance and repairs to keep your vehicle running safely, reliably and efficiently.', 'assets/images/social/og-image.jpg', true, 8, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('seo_terms', 'terms', 'Terms &amp; Conditions | Venom Racing', 'Venom Racing''s terms and conditions for performance tuning, fabrication and servicing.', 'Terms & Conditions | Venom Racing', 'Venom Racing''s terms and conditions.', 'assets/images/social/og-image.jpg', true, 9, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z')
insert into public.testimonials (id, name, subject, rating, review, photo, featured, source, date_text, sort_order, created_at, updated_at) values
  ('t_william-nalane', 'William Nalane', '', 5, 'Perfect service and quality work. No return job. Friendly and good customer care. Most important is the honesty.', '', true, 'Google', '5 days ago', 0, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_newqishke-du-preez', 'Newqishke du Preez', '', 5, 'Friendly & excellent service!', '', false, 'Google', '3 weeks ago', 1, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_robert-wagner', 'Robert Wagner', 'Servicing and detailing', 5, 'Always very good service and extremely clean workmanship. Very knowledgeable, no problem unsolvable. Very lucky to know where to take my Hilux or any other car for anything, even just a good wash and detailing!', '', true, 'Google', 'a month ago', 2, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_george-nel', 'George Nel', '', 5, 'I will always come to Drikus. Moerse satisfied. Thank you very much.', '', false, 'Google', 'a month ago', 3, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_forthefairies', 'ForTheFairies', 'Vehicle service', 5, 'Had my car serviced here. First time I''m happy with a service and it didn''t take an entire day. The staff is super friendly and on par with their servicing. Pricing is perfect too.', '', false, 'Google', 'a month ago', 4, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_bertus-swart', 'Bertus Swart', '', 5, 'Excellent service, professional workmanship, and the best customer service I''ve received - all delivered with a smile. Highly recommended!', '', true, 'Google', 'a month ago', 5, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_chane-steenberg', 'Chane Steenberg', '', 5, 'Very friendly service. Keeps in contact. Would 100% refer.', '', false, 'Google', '4 months ago', 6, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_ndumiso-mthethwa', 'Ndumiso Mthethwa', 'Conversion, respray and servicing', 5, 'They are the best in Witbank - car conversion, body respray, servicing the car. Top notch. Big up.', '', false, 'Google', '4 months ago', 7, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_pet-kgwedi', 'Pet Kgwedi', 'Performance diagnostics', 5, 'My car had performance issues, so I decided to take it to Venom for a checkup. Through their intensive diagnostic systems they managed to pick up the problem and got it fixed beyond perfection, I must say. Probably the neatest dealership in town. They just don''t disappoint.', '', true, 'Google', '6 months ago', 8, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_mpho-calvin-mokhethea', 'Mpho Calvin Mokhethea', 'Annual service - Mazda CX-5', 5, 'Took my Mazda CX-5 yesterday for an annual service - wow, Venom outdid themselves. Thank you guys for treating my car with care… it runs like new.', '', false, 'Google', '11 months ago', 9, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z'),
  ('t_dj-slash-productions-sa', 'DJ Slash Productions SA', 'Ford Focus ST225 repairs and fabrication', 5, 'Yet again, Dricus and the team have outdone themselves. I can''t thank you enough for treating my pride and joy as if it was my own. My Focus 225ST had a bad coolant leak, which they found by the Welsh plugs. They went further to find the coil pack wires were damaged and the intake pipe had issues, and sorted some leaks. On top of that they did a Y-piece straight pipe. One can see why this is a 5-star, RMI-Approved workshop. Keep up the good work - see you again soon!', '', true, 'Google', 'a year ago', 10, '2026-08-20T10:08:16.823Z', '2026-08-20T10:08:19.330Z')
insert into public.site_settings (key, value) values
  ('homepage', '{"heroTitle":"Where Performance Meets Precision.","heroSubtitle":"An RMI Accredited workshop and advanced accredited Dastek Unichip dealer in eMalahleni. In-house master tuner offering dyno and V-Box proven ECU tuning to ensure maximum performance, custom exhaust fabrication and precision automotive repairs.","heroBadge":"RMI Accredited · Official Dastek Unichip Dealer","btn1Text":"Explore Services","btn1Link":"performance.html","btn2Text":"Request Quote","btn2Link":"contact.html","heroImage":"","aboutEyebrow":"About Venom Racing","aboutTitle":"Precision Tuning, Proven On The Dyno","aboutText":"Venom Racing is a performance workshop based in eMalahleni, built on preferred performance brands including Dastek Unichip, De Graaf Exhaust Systems, BNB Exhausts, Viper Performance Exhausts and Cirrus Performance Intercoolers, plus in-house fabrication. Every calibration is professionally validated on the dyno or V-Box, proven to ensure maximum performance, safety and long-term reliability.","aboutText2":"As an RMI Accredited facility, we hold ourselves to manufacturer-level standards on tooling, technician qualification, and safety — while specialising in the performance work most franchise workshops won''t touch.","aboutBtnText":"Our Story","aboutBtnLink":"about.html","badgeTitle":"RMI Accredited","badgeText":"RMI Accredited workshop","showcase":[{"id":"sc_exhaust","url":"assets/images/about/home-exhaust.jpg","label":"Performance Exhaust","alt":"BMW M2 performance exhaust system by Venom Racing"},{"id":"sc_tools","url":"assets/images/about/home-tools.jpg","label":"Tools We Use","alt":"ECU programming, tuning and diagnostic tools used by Venom Racing"},{"id":"sc_dyno","url":"assets/images/about/home-dyno.jpg","label":"On The Dyno","alt":"BMW M4 on the Venom Racing dyno"}],"sections":{"services":{"eyebrow":"Our Expertise","title":"Master Tuning Specialists & Calibration","intro":"From ECU calibration and performance exhaust systems to complete servicing — every build is validated on the dyno or V-Box, proven to ensure maximum performance."},"why":{"eyebrow":"Why Choose Us","title":"26 Years of Experience, Exceptional Quality & Workmanship","intro":"Focused on precision, reliability and attention to every final detail."},"stages":{"eyebrow":"Performance Packages","title":"Choose Your Performance Stage","intro":"Every performance package is carefully designed to build on the previous stage, ensuring reliability, safety and maximum performance."},"process":{"eyebrow":"How It Works","title":"Our Performance Process","intro":""},"reviews":{"eyebrow":"Customer Testimonials","title":"Trusted by Performance Enthusiasts Across South Africa","intro":"Read genuine feedback from customers who have trusted Venom Racing with performance tuning, diagnostics, servicing and custom fabrication."},"faq":{"eyebrow":"Questions","title":"Frequently Asked Questions","intro":""},"contact":{"eyebrow":"Get In Touch","title":"Request A Quote","intro":"Tell us about your vehicle and what you''re looking to achieve — we''ll get back to you to schedule a consultation."}},"stats":[{"label":"Years of experience","value":"26+"},{"label":"Unichip experience","value":"20+ years"},{"label":"Accreditation","value":"RMI"},{"label":"Validation","value":"Dyno & V-Box"}],"ctaTitle":"Not sure which stage is right for your vehicle?","ctaText":"Tell us about your vehicle and what you are looking to achieve and we will get back to you to schedule a consultation.","ctaBtnText":"Book a Consultation","ctaBtnLink":"contact.html"}'::jsonb),
