  ('pages', '{"about":{"eyebrow":"About Venom Racing","title":"Precision Tuning\nWith Validated Results","text":"Venom Racing is a performance workshop based in eMalahleni, Mpumalanga, built around official dealer accreditation, in-house fabrication and tune validation with data logging.","text2":"Venom Racing is equipped with the latest state-of-the-art diagnostic, data logging and ECU tuning equipment, allowing every vehicle to be tuned safely, accurately and reliably. Our investment in modern technology ensures every calibration is validated for maximum performance, drivability and long-term reliability.","badgeTitle":"RMI Accredited","badgeText":"RMI Accredited workshop","techLabel":"Technology We Use","buttons":{"main":{"label":"Closing button","text":"Explore Our Services","link":"performance.html"}},"showcase":[{"id":"sc_ecu","url":"assets/images/about/ecu-remapping.jpg","label":"ECU Remapping","alt":"ECU remapping in WinOLS by Venom Racing"},{"id":"sc_res","url":"assets/images/about/results.jpg","label":"Validated Results","alt":"Dyno-validated results and data logging by Venom Racing"}],"sections":{"specialise":{"eyebrow":"","title":"What We Specialise In","intro":""}}},"performance":{"buttons":{"main":{"label":"Closing button","text":"Request a Quote","link":"contact.html"}},"sections":{"hero":{"eyebrow":"Performance Division","title":"Performance","intro":"Venom Racing''s performance division — meticulous care and attention to detail goes into every build, with products and quality backed by official dealer brands. Peak performance and outstanding quality, guaranteed and validated on our in-house dyno."},"ecu":{"eyebrow":"","title":"ECU Calibration & Remapping","intro":"Venom Performance tuning software from Stage 1 to Stage 3, with additional options such as AdBlue removal, DPF programming, EGR shut-off and deletes, hard-cut limiters, pops and bangs, burble effect, injector scaling, MAP and MAF sensor scaling, maximum RPM limit increase, stop/start disable, sport display activation, DTC deletes, speed-limit removal, swirl flaps, exhaust flaps, launch control activation and modification, cylinder-on-demand off, idle RPM adjustment, EVAP off, decat programming, map-switching solutions and many more to choose from."},"unichip":{"eyebrow":"Accredited Advanced Dastek Unichip Dealer","title":"Dastek Unichip Installations","intro":"Available for most vehicles for optimisation of fuelling, boost control, throttle control and timing for maximum safe power tuning results. For vehicles where direct ECU flashing is locked by the manufacturer or undesirable due to warranty constraints, we install and calibrate Dastek Unichip piggyback microcontrollers — connecting directly to the sensor array to modify signals in real time, without altering the factory ECU file."},"suppliers":{"eyebrow":"Trusted Suppliers","title":"Preferred Performance Brands","intro":"We proudly support and supply some of the world''s most trusted performance brands to ensure every build meets the highest standards of quality, reliability and performance."},"dyno":{"eyebrow":"Measured, Not Guessed","title":"Dyno Validation","intro":"Our in-house dyno facility validates every calibration, confirming real power gains and supplying before-and-after power figures — ensuring reliability and safety while delivering optimum power. Real-time logging and recording of measurements under load, checking reliability margins such as exhaust gas temperatures."},"exhaust":{"eyebrow":"In-House Fabrication","title":"Performance Exhaust Systems","intro":"High-quality, custom-manufactured performance exhausts — from bolt-on systems to bespoke downpipes. Precision-welded to an exacting standard for a premium finish, cleaner flow and an unmistakable tone."},"additives":{"eyebrow":"Trusted Products","title":"NF Additives","intro":"Premium fuel system treatments, engine protection and performance additives trusted by Venom Racing to maintain reliability and maximise performance."},"turbo":{"eyebrow":"Structural & Mechanical","title":"Turbo Upgrades & Hybrid Conversions","intro":"Venom Racing can supply a wide variety of bolt-on replacement upgrade turbos for most sports-driven vehicles. Custom big-turbo setups available in both journal-bearing and ball-bearing options, from various turbo manufacturers such as Garrett, Precision Turbo, Mamba Tech, G-Turbo series and many more."},"stages":{"eyebrow":"Performance Packages","title":"Choose Your Performance Stage","intro":"Every performance package is carefully designed to build on the previous stage, ensuring reliability, safety and maximum performance."},"process":{"eyebrow":"How It Works","title":"Our Performance Process","intro":""},"tuningportal":{"eyebrow":"Official Remote Tuning Portal","title":"Secure Online Tuning Portal","intro":"Purchase your ECU calibration directly through our secure online tuning portal. Available for workshops that require tuning assistance on DPF, EGR, etc., tuning shops that need Stage 1–3 tuning calibrations, or enthusiastic individuals who want the hands-on experience. From deleting DPF and other auxiliary systems to upgrading performance or replacing an existing tune, our online system lets you order professional calibrations supported by Venom Performance Tuning."}}},"services":{"buttons":{"hero":{"label":"Header button","text":"Book a Service","link":"contact.html"},"cta1":{"label":"Closing button","text":"Book a Service","link":"contact.html"},"cta2":{"label":"Closing button, secondary","text":"Contact Venom Racing","link":"contact.html"}},"sections":{"hero":{"eyebrow":"Workshop","title":"Services & Repairs","intro":"Professional servicing, maintenance and repairs to keep your vehicle running safely, reliably and efficiently."},"categories":{"eyebrow":"What We Offer","title":"Complete Workshop Care","intro":"Fleet maintenance and consumer servicing to full mechanical repairs — all carried out to manufacturer-compliant standards."},"workshop":{"eyebrow":"Behind the Scenes","title":"Workshop in Action","intro":"See our workshop in action with real servicing, repairs and mechanical work carried out by the Venom Racing team."},"why":{"eyebrow":"Why Choose Venom Racing","title":"Servicing You Can Trust","intro":""},"process":{"eyebrow":"How It Works","title":"Our Service Process","intro":""},"cta":{"eyebrow":"","title":"Need to Book a Service?","intro":"Talk to our team about servicing, repairs or a vehicle inspection."}}},"contact":{"buttons":{"portal":{"label":"Tuning portal button","text":"Open Tuning Portal","link":null},"directions":{"label":"Directions button","text":"Get Directions","link":null},"submit":{"label":"Enquiry form button","text":"Send WhatsApp Enquiry","link":null}},"portalText":"Purchase ECU tuning files securely through our official tuning portal. Fast, reliable and supported by Venom Racing.","labels":{"phone":"Phone","phone1":"Primary Contact","phone2":"Secondary Contact","email":"Email","email1":"General Enquiries","email2":"Venom Performance Tuning","social":"Follow Us","portal":"Online ECU Tuning Portal"},"sections":{"hero":{"eyebrow":"Get In Touch","title":"Contact Venom Racing","intro":"Tell us about your vehicle and what you''re looking to achieve — send us a WhatsApp enquiry and we''ll get straight back to you."},"map":{"eyebrow":"","title":"Visit Our Workshop","intro":"Professional Performance Tuning • Dyno Services • Mechanical Repairs"}}}}'::jsonb),
